// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./BatchTypes.sol";
import "./MintContract.sol";
import "./ControlContract.sol";

/**
 * @title VerificationContract
 * @notice Layer 3 of OriginPharm — read-only verification for all stakeholders.
 *
 * This contract has no state of its own and no write functions.
 * It reads from both MintContract and ControlContract and returns
 * the complete batch record in a single call.
 *
 * Used by:
 *   - Pharmacy: calls batchStatus(batchId) before receipt() to verify the on-chain
 *               record matches the physical delivery (medicine name, manufacturer,
 *               batch number, expiry date). If matched, proceeds to call receipt().
 *   - Consumer: scans QR code on medication box → reads batchId → calls batchStatus()
 *               to confirm the medicine completed the verified supply chain.
 *   - Regulator/Auditor: calls batchStatus() with batchId to audit the full
 *               custody trail and verified status of any batch.
 *
 * The QR code on the medication box encodes only the batchId.
 * All data lives on-chain. The QR code is generated by the application
 * layer when it detects the BatchReceived event from ControlContract.
 * It is printed by the pharmacist and attached to individual medication boxes.
 */


contract VerificationContract {

    // ─── State ────────────────────────────────────────────────────────────────

    /// @notice Reference to MintContract — source of batch data and verified status.
    MintContract public mintContract;

    /// @notice Reference to ControlContract — source of custody history and current custodian.
    ControlContract public controlContract;

    // ─── Constructor ──────────────────────────────────────────────────────────

    /**
     * @param mintContractAddress    Deployed address of MintContract.
     * @param controlContractAddress Deployed address of ControlContract.
     */
    constructor(address mintContractAddress, address controlContractAddress) {
        require(mintContractAddress != address(0), "VerificationContract: zero address");
        require(controlContractAddress != address(0), "VerificationContract: zero address");
        mintContract = MintContract(mintContractAddress);
        controlContract = ControlContract(controlContractAddress);
    }

    // helper to print status 
    function _statusLabel(BatchStatus status) internal pure returns (string memory) {
        if (status == BatchStatus.Produced)  return "Produced";
        if (status == BatchStatus.Released)  return "Released";
        if (status == BatchStatus.InTransit) return "InTransit";
        if (status == BatchStatus.Received)  return "Received";
        return "Unknown";
    }

    // ─── Verification Function ────────────────────────────────────────────────

    /**
     * @notice Returns the complete batch record for a given batchId.
     *         This is the single entry point for all stakeholders — pharmacy,
     *         consumer, regulator, and auditor.
     *
     *         Callable at any point in the batch lifecycle:
     *           After mintBatch():  status=Produced,  verified=false, empty trail
     *           After release():    status=Released,  verified=false, 1 custody record
     *           After shipment():   status=InTransit, verified=false, 2 custody records
     *           After receipt():    status=Received,  verified=true,  full trail
     *
     *         For consumers — only meaningful after the QR code exists on the box,
     *         which only happens after receipt() sets verified=true.
     *
     * @param batchId The unique batch identifier — scanned from QR code or searched directly.
     *
     * @return medicineName     Human-readable medicine name e.g. "Amoxicillin 500mg".
     * @return batchNumber      Manufacturer's internal batch reference e.g. "BATCH-001".
     * @return manufacturerName Owner-verified manufacturer name e.g. "Pfizer Australia Pty Ltd".
     * @return manufacturer     Wallet address of the minting manufacturer.
     * @return manufactureDate  Unix timestamp of when the batch was minted.
     * @return expiryDate       Unix timestamp of the batch expiry date.
     * @return status           Current BatchStatus enum value.
     * @return verified         True if receipt() has closed the cycle successfully.
     * @return currentOwner     Wallet address of the current batch custodian.
     * @return custodyTrail     Full ordered array of CustodyRecords from mint to present.
     */
     
     
    function batchStatus(uint256 batchId)
        external
        view
        returns (
            string memory medicineName,
            string memory batchNumber,
            string memory manufacturerName,
            address manufacturer,
            uint256 manufactureDate,
            uint256 expiryDate,
            string memory  status,
            bool verified,
            address currentOwner,
            CustodyRecord[] memory custodyTrail
        )
    {
        require(mintContract.batchExists(batchId), "VerificationContract: batch does not exist");

        BatchData memory batch = mintContract.getBatch(batchId);

        medicineName = batch.medicineName;
        batchNumber = batch.batchNumber;
        manufacturerName = batch.manufacturerName;
        manufacturer = batch.manufacturer;
        manufactureDate  = batch.manufactureDate;
        expiryDate = batch.expiryDate;
        status = _statusLabel(batch.status);
        verified = batch.verified;
        currentOwner = controlContract.currentCustodian(batchId);
        custodyTrail = controlContract.getCustodyHistory(batchId);
    }
}

contracts/MintContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./BatchTypes.sol";

/**
 * @title MintContract
 * @notice Handles minting of pharmaceutical batch tokens.
 *         Only authorised manufacturers may mint new batches.
 *
 * @dev This is a simplified token registry (not a full ERC-721).
 *      Each batch gets a unique tokenId incremented from 1.
 *      The ControlContract reads from this contract to validate batches.
 */
/**
 * @title MintContract
 * @notice Layer 1 of OriginPharm — participant registration and batch token creation.
 *
 * The Owner (OriginPharm / TGA equivalent) registers every supply chain participant
 * with their verified wallet address and real-world name before any supply chain
 * activity is possible. Participants cannot self-report their own name.
 *
 * When a new batch of medicine is produced, the manufacturer calls mintBatch().
 * A unique batchId is assigned and the manufacturer's verified name is read
 * automatically from the registry — it is never passed as a parameter.
 *
 * Only ControlContract can update batch state via onlyControlContract modifier.
 * No external wallet can manipulate batch records directly.
 *
 * Deployment note:
 *   1. Deploy MintContract
 *   2. Deploy ControlContract with MintContract address
 *   3. Call setControlContract() on MintContract with ControlContract address
 */
contract MintContract {

    // ─── State ────────────────────────────────────────────────────────────────

    /// @notice Owner wallet — TGA / OriginPharm platform.
    ///         Controls all participant registration. Has no supply chain write access.
    address public owner;

    /// @notice Address of the deployed ControlContract.
    ///         Set post-deployment via setControlContract(). Used for onlyControlContract.
    address public controlContractAddress;

    /// @notice Auto-incrementing batchId counter. Starts at 1.
    uint256 private _nextBatchId;

    /// @notice Maps batchId → BatchData for every minted batch.
    mapping(uint256 => BatchData) private _batches;

    /// @notice Registry of authorised manufacturers.
    ///         Stores owner-verified wallet address and real-world name.
    mapping(address => VerifiedParty) public authorisedManufacturers;

    // ─── Events ───────────────────────────────────────────────────────────────

    event ManufacturerAuthorised(address indexed manufacturer, string name);
    event ManufacturerRevoked(address indexed manufacturer);
    event ControlContractSet(address indexed controlContract);
    event BatchMinted(
        uint256 indexed batchId,
        address indexed manufacturer,
        string  manufacturerName,
        string  medicineName,
        string  batchNumber,
        uint256 expiryDate
    );
    event BatchVerified(uint256 indexed batchId);

    // ─── Modifiers ────────────────────────────────────────────────────────────

    /// @notice Restricts function to the contract owner (TGA / OriginPharm).
    modifier onlyOwner() {
        require(msg.sender == owner, "MintContract: caller is not owner");
        _;
    }

    /// @notice Restricts function to authorised manufacturers only.
    modifier onlyManufacturer() {
        require(
            authorisedManufacturers[msg.sender].isAuthorised,
            "MintContract: caller is not an authorised manufacturer"
        );
        _;
    }

    /// @notice Restricts function to ControlContract only.
    ///         Prevents any external wallet from directly mutating batch state.
    modifier onlyControlContract() {
        require(
            msg.sender == controlContractAddress,
            "MintContract: caller is not the ControlContract"
        );
        _;
    }

    // ─── Constructor ──────────────────────────────────────────────────────────

    constructor() {
        owner = msg.sender;
        _nextBatchId = 1;
    }

    // ─── Owner Functions ──────────────────────────────────────────────────────

    /**
     * @notice Sets the ControlContract address after deployment.
     *         Must be called once before any supply chain activity begins.
     *         Enables the onlyControlContract modifier on updateStatus() and setVerified().
     * @param _controlContractAddress Deployed address of ControlContract.
     */
    function setControlContract(address _controlContractAddress) external onlyOwner {
        require(_controlContractAddress != address(0), "MintContract: zero address");
        controlContractAddress = _controlContractAddress;
        emit ControlContractSet(_controlContractAddress);
    }

    /**
     * @notice Registers a manufacturer with their verified wallet address and real-world name.
     *         Name is set by the Owner — the manufacturer cannot self-report their identity.
     *         In practice, names are sourced from the TGA verified manufacturer database.
     * @param manufacturer Wallet address of the manufacturer.
     * @param name         Owner-verified real-world name e.g. "Pfizer Australia Pty Ltd".
     */
    function authoriseManufacturer(address manufacturer, string calldata name) external onlyOwner {
        require(manufacturer != address(0), "MintContract: zero address");
        require(bytes(name).length > 0, "MintContract: name cannot be empty");
        authorisedManufacturers[manufacturer] = VerifiedParty({ isAuthorised: true, name: name });
        emit ManufacturerAuthorised(manufacturer, name);
    }

    /**
     * @notice Revokes a manufacturer's authorisation.
     *         Revoked manufacturers can no longer call mintBatch().
     * @param manufacturer Wallet address to revoke.
     */
    function revokeManufacturer(address manufacturer) external onlyOwner {
        require(authorisedManufacturers[manufacturer].isAuthorised, "MintContract: not currently authorised");
        authorisedManufacturers[manufacturer].isAuthorised = false;
        emit ManufacturerRevoked(manufacturer);
    }

    // ─── Manufacturer Functions ───────────────────────────────────────────────

    /**
     * @notice Mints a batch token representing a newly produced pharmaceutical batch.
     *         Called by the manufacturer when a physical batch of medicine is produced.
     *         The manufacturer's verified name is read from the registry automatically —
     *         they do not pass their own name as a parameter.
     *
     * @param medicineName Human-readable name of the medicine e.g. "Amoxicillin 500mg".
     * @param batchNumber  Manufacturer's internal batch reference e.g. "BATCH-001".
     * @param expiryDate   Unix timestamp of the batch expiry date — must be in the future.
     * @return batchId     The unique ID assigned to this batch. Travels on the packing slip.
     */
    function mintBatch(
        string calldata medicineName,
        string calldata batchNumber,
        uint256 expiryDate
    ) external onlyManufacturer returns (uint256 batchId) {
        require(bytes(medicineName).length > 0, "MintContract: medicineName cannot be empty");
        require(bytes(batchNumber).length > 0,  "MintContract: batchNumber cannot be empty");
        require(expiryDate > block.timestamp,   "MintContract: expiry date must be in the future");

        batchId = _nextBatchId++;

        // Read manufacturer's verified name from the registry — never self-reported
        string memory verifiedName = authorisedManufacturers[msg.sender].name;

        _batches[batchId] = BatchData({
            batchId:  batchId,
            medicineName:     medicineName,
            batchNumber:      batchNumber,
            manufacturerName: verifiedName,
            manufactureDate:  block.timestamp,
            expiryDate:       expiryDate,
            manufacturer:     msg.sender,
            status:           BatchStatus.Produced,
            verified:         false
        });

        emit BatchMinted(batchId, msg.sender, verifiedName, medicineName, batchNumber, expiryDate);
    }

    // ─── ControlContract-Only Functions ──────────────────────────────────────

    /**
     * @notice Updates the status of a batch as it progresses through the supply chain.
     *         Called by ControlContract only — no external wallet can change batch state.
     * @param batchId   The batch to update.
     * @param newStatus The new BatchStatus value.
     */
    function updateStatus(uint256 batchId, BatchStatus newStatus) external onlyControlContract {
        require(batchExists(batchId), "MintContract: batch does not exist");
        _batches[batchId].status = newStatus;
    }

    /**
     * @notice Sets verified = true when receipt() closes the supply chain cycle.
     *         Called by ControlContract only after the pharmacist confirms delivery.
     *         Triggers the QR code generation event on the application layer.
     * @param batchId The batch to mark as verified.
     */
    function setVerified(uint256 batchId) external onlyControlContract {
        require(batchExists(batchId), "MintContract: batch does not exist");
        _batches[batchId].verified = true;
        emit BatchVerified(batchId);
    }

    // ─── Read Functions ───────────────────────────────────────────────────────

    /**
     * @notice Returns the full BatchData struct for a given batchId.
     *         Includes manufacturerName, verified flag, and current status.
     * @param batchId The batch to look up.
     */
    function getBatch(uint256 batchId) external view returns (BatchData memory) {
        require(batchExists(batchId), "MintContract: batch does not exist");
        return _batches[batchId];
    }

    /**
     * @notice Returns true if a batchId has been minted.
     * @param batchId The batch to check.
     */
    function batchExists(uint256 batchId) public view returns (bool) {
        return _batches[batchId].manufacturer != address(0);
    }

    /**
     * @notice Returns the verified name of a registered manufacturer.
     *         Used by ControlContract to display manufacturer identity in custody records.
     * @param manufacturer Wallet address of the manufacturer.
     */
    function getManufacturerName(address manufacturer) external view returns (string memory) {
        return authorisedManufacturers[manufacturer].name;
    }
}

contracts/ControlContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./BatchTypes.sol";
import "./MintContract.sol";

/**
 * @title ControlContract
 * @notice Layer 2 of OriginPharm — the supply chain pipeline.
 *
 * Manages all custody transfers across the supply chain:
 *   Manufacturer → release()  → Distributor
 *   Distributor  → shipment() → Pharmacy
 *   Pharmacy     → receipt()  → cycle closes, verified = true, QR code generated
 *
 * Access is enforced through role-based modifiers:
 *   onlyManufacturer → release()
 *   onlyDistributor  → shipment()
 *   onlyPharmacy     → receipt()
 *
 * Custodian enforcement is applied across all three functions:
 *   require(msg.sender == currentCustodian[batchId])
 *   Only the current token holder can progress the batch.
 *
 * All state changes in MintContract are routed through this contract only.
 * No external wallet can mutate batch state directly.
 *
 * Deployment note:
 *   Deploy after MintContract. Pass MintContract address to constructor.
 *   Then call MintContract.setControlContract(thisAddress) to complete the wiring.
 */
contract ControlContract {

    // ─── State ────────────────────────────────────────────────────────────────

    /// @notice Reference to MintContract for batch lookups and state updates.
    MintContract public mintContract;

    /// @notice Owner wallet — same deployer as MintContract.
    address public owner;

    /// @notice Registry of authorised distributors with owner-verified names.
    mapping(address => VerifiedParty) public authorisedDistributors;

    /// @notice Registry of authorised pharmacies with owner-verified names.
    mapping(address => VerifiedParty) public authorisedPharmacies;

    /// @notice Full ordered custody trail per batch. Appended by each pipeline function.
    mapping(uint256 => CustodyRecord[]) private _custodyHistory;

    /// @notice Current custodian (token holder) per batch.
    ///         Updated by each pipeline function. Used for custodian enforcement.
    mapping(uint256 => address) public currentCustodian;

    // ─── Events ───────────────────────────────────────────────────────────────

    event DistributorAuthorised(address indexed distributor, string name);
    event DistributorRevoked(address indexed distributor);
    event PharmacyAuthorised(address indexed pharmacy, string name);
    event PharmacyRevoked(address indexed pharmacy);

    event BatchReleased(
        uint256 indexed batchId,
        address indexed manufacturer,
        address indexed distributor,
        uint256 timestamp
    );
    event BatchShipped(
        uint256 indexed batchId,
        address indexed distributor,
        address indexed pharmacy,
        string  notes,
        uint256 timestamp
    );
    event BatchReceived(
        uint256 indexed batchId,
        address indexed pharmacy,
        uint256 timestamp
    );

    // ─── Modifiers ────────────────────────────────────────────────────────────

    /// @notice Restricts function to the contract owner.
    modifier onlyOwner() {
        require(msg.sender == owner, "ControlContract: caller is not owner");
        _;
    }

    /// @notice Restricts function to authorised manufacturers (verified in MintContract).
    modifier onlyManufacturer() {
        (bool isAuth, ) = mintContract.authorisedManufacturers(msg.sender);
        require(isAuth, "ControlContract: caller is not an authorised manufacturer");
        _;
    }

    /// @notice Restricts function to authorised distributors.
    modifier onlyDistributor() {
        require(
            authorisedDistributors[msg.sender].isAuthorised,
            "ControlContract: caller is not an authorised distributor"
        );
        _;
    }

    /// @notice Restricts function to authorised pharmacies.
    modifier onlyPharmacy() {
        require(
            authorisedPharmacies[msg.sender].isAuthorised,
            "ControlContract: caller is not an authorised pharmacy"
        );
        _;
    }

    // ─── Constructor ──────────────────────────────────────────────────────────

    /**
     * @param mintContractAddress Deployed address of MintContract.
     */
    constructor(address mintContractAddress) {
        require(mintContractAddress != address(0), "ControlContract: zero address");
        owner = msg.sender;
        mintContract = MintContract(mintContractAddress);
    }

    // ─── Owner Functions — Role Registration ──────────────────────────────────

    /**
     * @notice Registers a distributor with their owner-verified name.
     *         In practice, names are sourced from the TGA verified participant database.
     * @param distributor Wallet address of the distributor.
     * @param name        Owner-verified real-world name e.g. "AusPost Logistics".
     */
    function authoriseDistributor(address distributor, string calldata name) external onlyOwner {
        require(distributor != address(0), "ControlContract: zero address");
        require(bytes(name).length > 0,   "ControlContract: name cannot be empty");
        authorisedDistributors[distributor] = VerifiedParty({ isAuthorised: true, name: name });
        emit DistributorAuthorised(distributor, name);
    }

    /**
     * @notice Revokes a distributor's authorisation.
     * @param distributor Wallet address to revoke.
     */
    function revokeDistributor(address distributor) external onlyOwner {
        require(authorisedDistributors[distributor].isAuthorised, "ControlContract: not currently authorised");
        authorisedDistributors[distributor].isAuthorised = false;
        emit DistributorRevoked(distributor);
    }

    /**
     * @notice Registers a pharmacy with their owner-verified name.
     * @param pharmacy Wallet address of the pharmacy.
     * @param name     Owner-verified real-world name e.g. "Terry White — George St".
     */
    function authorisePharmacy(address pharmacy, string calldata name) external onlyOwner {
        require(pharmacy != address(0), "ControlContract: zero address");
        require(bytes(name).length > 0, "ControlContract: name cannot be empty");
        authorisedPharmacies[pharmacy] = VerifiedParty({ isAuthorised: true, name: name });
        emit PharmacyAuthorised(pharmacy, name);
    }

    /**
     * @notice Revokes a pharmacy's authorisation.
     * @param pharmacy Wallet address to revoke.
     */
    function revokePharmacy(address pharmacy) external onlyOwner {
        require(authorisedPharmacies[pharmacy].isAuthorised, "ControlContract: not currently authorised");
        authorisedPharmacies[pharmacy].isAuthorised = false;
        emit PharmacyRevoked(pharmacy);
    }

    // ─── Supply Chain Pipeline ────────────────────────────────────────────────

    /**
     * @notice Step 1 — Manufacturer releases a produced batch to a distributor.
     *         The batchId travels on the packing slip accompanying the physical handover.
     *         Status: Produced → Released.
     *
     * @param batchId     The batch being released.
     * @param distributor Wallet address of the receiving distributor — must be authorised.
     */
    function release(uint256 batchId, address distributor) external onlyManufacturer {
        require(mintContract.batchExists(batchId), "ControlContract: batch does not exist");
        require(authorisedDistributors[distributor].isAuthorised, "ControlContract: distributor is not authorised");

        BatchData memory batch = mintContract.getBatch(batchId);

        require(batch.status == BatchStatus.Produced, "ControlContract: batch must be Produced to release");
        require(msg.sender == batch.manufacturer,     "ControlContract: caller is not the batch manufacturer");

        mintContract.updateStatus(batchId, BatchStatus.Released);

        _appendCustody(batchId, msg.sender, distributor, BatchStatus.Released, "");
        currentCustodian[batchId] = distributor;

        emit BatchReleased(batchId, msg.sender, distributor, block.timestamp);
    }

    /**
     * @notice Step 2 — Distributor records a shipment to the pharmacy.
     *         The batchId travels on the delivery documentation to the pharmacy.
     *         Status: Released → InTransit.
     *
     * @param batchId   The batch being shipped.
     * @param pharmacy  Wallet address of the receiving pharmacy — must be authorised.
     * @param notes     Optional carrier notes e.g. "AusPost Ref: AUS-993, Temp: 2-8°C".
     */
    function shipment(uint256 batchId, address pharmacy, string calldata notes) external onlyDistributor {
        require(mintContract.batchExists(batchId), "ControlContract: batch does not exist");
        require(authorisedPharmacies[pharmacy].isAuthorised, "ControlContract: pharmacy is not authorised");
        require(msg.sender == currentCustodian[batchId], "ControlContract: caller is not the current custodian");

        BatchData memory batch = mintContract.getBatch(batchId);

        require(
            batch.status == BatchStatus.Released || batch.status == BatchStatus.InTransit,
            "ControlContract: batch must be Released or InTransit to ship"
        );

        mintContract.updateStatus(batchId, BatchStatus.InTransit);

        _appendCustody(batchId, msg.sender, pharmacy, BatchStatus.InTransit, notes);
        currentCustodian[batchId] = pharmacy;

        emit BatchShipped(batchId, msg.sender, pharmacy, notes, block.timestamp);
    }

    /**
     * @notice Step 3 — Pharmacy confirms delivery and closes the supply chain cycle.
     *
     *         Before calling this function, the pharmacist should call
     *         VerificationContract.batchStatus(batchId) to read the on-chain record
     *         and compare it against the physical delivery. If the medicine name,
     *         manufacturer, batch number, and expiry date all match — proceed.
     *
     *         On success:
     *           - verified is set to true in MintContract
     *           - status moves to Received
     *           - BatchReceived event is emitted
     *           - The application layer detects the event and generates the printable QR code
     *           - The pharmacist prints the QR code and attaches it to medication boxes
     *
     *         The QR code encodes only the batchId. All data lives on-chain.
     *         Consumers scan the QR and call batchStatus(batchId) to verify.
     *
     * @param batchId The batch being received — taken from the packing slip.
     */
    function receipt(uint256 batchId) external onlyPharmacy {
        require(mintContract.batchExists(batchId), "ControlContract: batch does not exist");
        require(msg.sender == currentCustodian[batchId], "ControlContract: caller is not the current custodian");

        BatchData memory batch = mintContract.getBatch(batchId);

        require(batch.status == BatchStatus.InTransit, "ControlContract: batch must be InTransit to receive");

        // Close the cycle — set verified = true and status = Received
        mintContract.setVerified(batchId);
        mintContract.updateStatus(batchId, BatchStatus.Received);

        _appendCustody(batchId, currentCustodian[batchId], msg.sender, BatchStatus.Received, "");
        currentCustodian[batchId] = msg.sender;

        // Emitting BatchReceived signals the application layer to generate the printable QR code
        emit BatchReceived(batchId, msg.sender, block.timestamp);
    }

    // ─── Internal Helpers ─────────────────────────────────────────────────────

    function _appendCustody(
        uint256 batchId,
        address from,
        address to,
        BatchStatus status,
        string memory notes
    ) internal {
        _custodyHistory[batchId].push(CustodyRecord({
            from:      from,
            to:        to,
            status:    status,
            timestamp: block.timestamp,
            notes:     notes
        }));
    }

    // ─── Read Functions ───────────────────────────────────────────────────────

    /**
     * @notice Returns the full ordered custody trail for a batch.
     *         Each record represents one handoff in the supply chain.
     * @param batchId The batch to query.
     */
    function getCustodyHistory(uint256 batchId) external view returns (CustodyRecord[] memory) {
        return _custodyHistory[batchId];
    }
}

